33	/** Basic URL validation — checks structure, not reachability */
34	function isValidUrl(str: string): boolean {
35	  try {
36	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
37	    return url.protocol === "https:" || url.protocol === "http:";
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	/** Normalize URL: prepend https:// if missing */
44	function normalizeUrl(str: string): string {
45	  const trimmed = str.trim();
46	  if (!trimmed) return trimmed;
47	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
48	  return `https://${trimmed}`;
49	}
50	
51	// ── Map scan status to step index ───────────────────────────────
52	
53	function statusToStep(status: string): number {
54	  switch (status) {
55	    case "pending": return 0;
56	    case "analyzing": return 3;
57	    case "completed": return SCAN_STEPS.length;
58	    case "failed": return -1;
59	    default: return 0;
60	  }
61	}
62	
63	const Scan = () => {
64	  const navigate = useNavigate();
65	  const [searchParams] = useSearchParams();
66	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
67	  const [pageType, setPageType] = useState<PageType>(
68	    (searchParams.get("type") as PageType) || "landing"
69	  );
70	  const [urlError, setUrlError] = useState<string | null>(null);
71	
72	  // activeScanId drives the polling query
73	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
74	  const [simulatedStep, setSimulatedStep] = useState(-1);
75	
76	  const inputId = useId();
77	  const { user, profile } = useAuth();
78	  const isAuthenticated = !!user;
79	  const createScan = useCreateScan();
80	
81	  const scansUsed = profile?.scans_used ?? 0;
82	  const scanLimit = profile?.scan_limit ?? 3;
83	  const scansRemaining = scanLimit - scansUsed;
84	  const atLimit = scansRemaining <= 0;
85	
86	  // Poll the scan row while it's pending/analyzing
87	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
88	    refetchInterval: activeScanId ? 2000 : false,
89	  });
90	
91	  const isAnalyzing = activeScanId !== null;
92	  const normalizedUrl = normalizeUrl(rawUrl);
93	
94	  const totalSteps = SCAN_STEPS.length;
95	  const currentStep = isAnalyzing
96	    ? pollingScan
97	      ? statusToStep(pollingScan.status)
98	      : simulatedStep
99	    : -1;
100	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
101	
102	  // When polling finds a completed/failed scan, navigate or show error
103	  useEffect(() => {
104	    if (!pollingScan) return;
105	    if (pollingScan.status === "completed") {
106	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
107	    } else if (pollingScan.status === "failed") {
108	      setActiveScanId(null);
109	      setSimulatedStep(-1);
110	      toast.error("Scan failed. Please try again.", {
111	        action: { label: "Retry", onClick: () => startAnalysis() },
112	      });
113	    }
114	    // eslint-disable-next-line react-hooks/exhaustive-deps
115	  }, [pollingScan?.status]);
116	
117	  // Simulate step progression while waiting for the edge function
118	  useEffect(() => {
119	    if (!isAnalyzing || !activeScanId) return;
120	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
121	    if (simulatedStep >= totalSteps - 1) return;
122	
123	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
124	    const timer = setTimeout(
125	      () => setSimulatedStep((prev) => prev + 1),
126	      durations[simulatedStep] ?? 1200
127	    );
128	    return () => clearTimeout(timer);
129	    // totalSteps is derived from a constant — safe to omit
130	    // eslint-disable-next-line react-hooks/exhaustive-deps
131	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
132	
133	  const startAnalysis = useCallback(() => {
134	    setUrlError(null);
135	    if (!rawUrl.trim()) {
136	      setUrlError("Please enter a URL.");
137	      return;
138	    }
139	    if (!isValidUrl(normalizedUrl)) {
140	      setUrlError("Enter a valid URL like https://example.com/page");
141	      return;
142	    }
143	
