    );
  }
  if (status === "analyzing") {
    return (
      <Badge
        variant="outline"
        className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-[11px] font-medium animate-pulse"
      >
        Analyzing
      </Badge>
    );
  }
  return (
    <Badge variant="outline" className="text-[11px]">
      {status}
    </Badge>
  );
}

