        <div className="flex h-14 items-center justify-between px-3 border-b border-white/[0.06]">
          {!collapsed && (
            <div className="flex items-center gap-2.5">
              <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary shrink-0">
                <ScanLine className="h-3.5 w-3.5 text-white" />
              </div>
              <div className="flex flex-col leading-tight">
                <span className="text-[13px] font-semibold text-white tracking-tight">
                  ConvertScan
                </span>
                <span className="text-[10px] text-white/30 font-medium uppercase tracking-wider">
                  Admin
                </span>
              </div>
            </div>
          )}
          {collapsed && (
            <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary mx-auto">
              <ScanLine className="h-3.5 w-3.5 text-white" />
            </div>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 px-2 py-3 space-y-0.5 overflow-y-auto">
          {NAV_ITEMS.map((item) => {
            const active = isActive(item.href);
            return (
              <div key={item.href}>
                {item.disabled ? (
                  <div
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 cursor-not-allowed opacity-30",
                      collapsed ? "justify-center" : ""
                    )}
                    title={item.disabled ? `Coming soon` : item.title}
                  >
                    <item.icon className="h-4 w-4 text-white/60 shrink-0" />
                    {!collapsed && (
                      <span className="text-[13px] text-white/60 flex-1 truncate">
                        {item.title}
                      </span>
                    )}
                    {!collapsed && item.badge && (
                      <Badge
                        variant="outline"
                        className="border-white/10 text-white/25 text-[9px] px-1 py-0 leading-tight"
