                        {item.badge}
                      </Badge>
                    )}
                  </div>
                ) : (
                  <Link
                    to={item.href}
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 transition-colors duration-150",
                      collapsed ? "justify-center" : "",
                      active
                        ? "bg-white/[0.08] text-white"
                        : "text-white/50 hover:bg-white/[0.04] hover:text-white/80"
                    )}
                    title={collapsed ? item.title : undefined}
                  >
                    <item.icon
                      className={cn(
                        "h-4 w-4 shrink-0",
                        active ? "text-primary" : ""
                      )}
                    />
                    {!collapsed && (
                      <span
                        className={cn(
                          "text-[13px] truncate",
                          active ? "font-medium" : ""
                        )}
                      >
                        {item.title}
                      </span>
                    )}
                  </Link>
                )}
              </div>
            );
          })}

          <Separator className="my-2 bg-white/[0.06]" />

          <Link
            to="/dashboard"
            className={cn(
              "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-white/40 hover:text-white/70 hover:bg-white/[0.04] transition-colors",
              collapsed ? "justify-center" : ""
            )}
            title={collapsed ? "Back to App" : undefined}
          >
            <ArrowLeft className="h-4 w-4 shrink-0" />
            {!collapsed && (
              <span className="text-[13px]">Back to App</span>
            )}
          </Link>
        </nav>

        {/* Footer */}
        <div className="border-t border-white/[0.06] p-2 space-y-2">
          {!collapsed && (
            <div className="flex items-center gap-2 px-1.5 py-1 rounded-md">
              <Avatar className="h-6 w-6 shrink-0">
                {profile?.avatar_url && (
                  <AvatarImage src={profile.avatar_url} alt={displayName} />
                )}
                <AvatarFallback className="bg-primary/20 text-[9px] font-medium text-primary">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <p className="text-[11px] font-medium text-white truncate">
                  {displayName.split(" ")[0]}
                </p>
                <p className="text-[10px] text-white/30 capitalize">
                  {profile?.role?.replace("_", " ") ?? "admin"}
                </p>
              </div>
            </div>
          )}
          <button
            onClick={() => setCollapsed((c) => !c)}
            className="flex w-full items-center justify-center rounded-md p-1.5 text-white/25 hover:bg-white/[0.04] hover:text-white/50 transition-colors"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {collapsed ? (
              <ChevronRight className="h-4 w-4" />
            ) : (
              <ChevronLeft className="h-4 w-4" />
            )}
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Admin top bar */}
        <header className="flex h-14 items-center justify-between border-b border-border/50 bg-white/80 backdrop-blur-sm px-6 shrink-0">
          <div className="flex items-center gap-3">
            <Badge
              className="bg-primary/8 text-primary border-primary/15 text-[11px] font-medium px-2 py-0.5"
            >
              Admin
            </Badge>
            <span className="text-border text-sm">/</span>
            <span className="text-sm text-muted-foreground">
              {location.pathname === "/admin"
                ? "Dashboard"
                : location.pathname
                    .split("/")
                    .filter(Boolean)
                    .slice(1)
                    .map((s) =>
                      s
                        .split("-")
                        .map((w) => w[0].toUpperCase() + w.slice(1))
                        .join(" ")
                    )
                    .join(" / ")}
            </span>
          </div>

          <div className="flex items-center gap-2">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="flex items-center gap-2 rounded-lg px-2 py-1 hover:bg-muted/50 transition-colors">
                  <Avatar className="h-6 w-6">
                    {profile?.avatar_url && (
                      <AvatarImage src={profile.avatar_url} alt={displayName} />
                    )}
                    <AvatarFallback className="bg-primary/8 text-[10px] font-medium text-primary">
                      {initials}
                    </AvatarFallback>
                  </Avatar>
                  <div className="hidden sm:flex flex-col items-start leading-tight">
                    <span className="text-[12px] font-medium text-foreground">
                      {displayName.split(" ")[0]}
                    </span>
                    <span className="text-[10px] text-muted-foreground capitalize">
                      {profile?.role?.replace("_", " ") ?? "admin"}
                    </span>
                  </div>
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-48">
                <div className="px-2 py-1.5">
                  <p className="text-sm font-medium text-foreground">{displayName}</p>
                  <p className="text-xs text-muted-foreground">{profile?.email ?? ""}</p>
                </div>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => navigate("/settings")}>
                  <User className="mr-2 h-3.5 w-3.5" />
                  Profile
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => navigate("/settings")}>
                  <Settings className="mr-2 h-3.5 w-3.5" />
                  Settings
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleLogout} className="text-destructive">
                  <LogOut className="mr-2 h-3.5 w-3.5" />
                  Log out
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 p-4 md:p-6 lg:p-8 bg-background overflow-auto">
          <div className="mx-auto max-w-[1140px]">
            <Outlet />
          </div>
        </main>
      </div>
    </div>
  );
}
